import assert from 'node:assert';
import { createState, frame } from '../game/neon.js';

test('D1 - No bounce: ball should reflect when hitting a brick', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  // Position ball to hit the top of the first brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 5; // overlapping slightly
  state.ball.vy = 100; // moving DOWN
  state.ball.vx = 0;

  const ctx = {
    fillStyle: '',
    fillRect: () => {},
    fillText: () => { },
    beginPath: () => {},
    arc: () => {},
    fill: () => {}
  };

  frame(ctx, state);

  assert.strictEqual(state.ball.vy < 0, true, 'Ball should have bounced UP');
});

