import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createState, frame } from '../game/neon.js';

test('D1 - No bounce: ball should reflect when hitting a brick (TOP)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 5; // overlapping slightly
  state.ball.vy = 100; // moving DOWN
  state.ball.vx = 0;

  const ctx = {
    fillStyle: '',
    fillRect: () => {},
    fillText: () => { },
    beginPath: () => {},
    arc: () => {},
    fill: () => {}
  };

  frame(ctx, state);
  assert.ok(state.ball.vy < 0, 'Ball should have bounced UP');
});

test('D1 - No bounce: ball should reflect when hitting a brick (SIDE)', () => {
  const state = createState(1);
  const brick = state.bricks[0];
  state.ball.x = brick.x - 5; // overlapping slightly
  state.ball.y = brick.y + brick.h / 2;
  state.ball.vx = 100; // moving RIGHT
  state.ball.vy = 0;

  const ctx = {
    fillStyle: '',
    fillRect: () => {},
    fillText: () => { },
    beginPath: () => {},
    arc: () => {},
    fill: () => {}
  };

  frame(ctx, state);
  assert.ok(state.ball.vx < 0, 'Ball should have bounced LEFT');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createState, frame } from '../game/neon.js';

test('D2 - Double inversion: ball should reflect only once even if hitting two bricks', () => {
  const state = createState(1);
  const b1 = state.bricks[0];
  const b2 = state.bricks[1];

  // Position ball to overlap both bricks on the seam
  state.ball.x = b1.x + b1.w - 1; // overlap b1 slightly
  state.ball.y = b1.y + b1.h / 2;
  state.ball.vx = 100; // moving RIGHT
  state.ball.vy = 0;

  // Ensure b2 is immediately to the right (it is, as per makeBricks)
  // b2.x = b1.x + b1.w + BRICK_GAP. 
  // So the ball at b1.x + b1.w - 1 is NOT yet overlapping b2 if BRICK_GAP > 0.
  // BRICK_GAP = 8.
  // To overlap both, the ball must span the gap.
  // Ball diameter = 14. Gap = 8. It's possible.

  state.ball.x = b1.x + b1.w - 2; // overlap b1 by 2px
  // Ball right edge = b1.x + b1.w - 2 + 7 = b1.x + b1.w + 5.
  // b2.x = b1.x + b1.w + 8.
  // Still not overlapping b2.

  // Let's move ball more to the right.
  state.ball.x = b1.x + b1.w + 3; 
  // Ball left edge = b1.x + b1.w + 3 - 7 = b1.x + b1.w - 4. Overlaps b1.
  // Ball right edge = b1.x + b1.w + 3 + 7 = b1.x + b1.w + 10. Overlaps b2 (since b2.x = b1.x + b1.w + 8).

  state.ball.vx = 100;
  state.ball.vy = 0;

  const ctx = {
    fillStyle: '',
    fillRect: () => {},
    fillText: () => { },
    beginPath: () => {},
    arc: () => {},
    fill: () => {}
  };

  frame(ctx, state);

  assert.ok(state.ball.vx < 0, 'Ball should have bounced LEFT once');
});

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createState, step, frame } from '../game/neon.js';

test('D3 - Tunneling: ball should not pass through brick at high speed (level 6+)', () => {
  const state = createState(6); // High level, high speed
  const brick = state.bricks[0];

  // Position ball just above the brick
  state.ball.x = brick.x + brick.w / 2;
  state.ball.y = brick.y - 10; 
  state.ball.vy = 680; // This is roughly the speed at level 6
  state.ball.vx = 0;

  const ctx = {
    fillStyle: '',
    fillRect: () => {},
    fillText: () => { },
    beginPath: () => {},
    arc: () => {},
    fill: () => {}
  };

  // Simulation step: move and check collision
  // In a real frame, step() is called then frame()
  const dt = 0.05; // Max dt
  step(state, dt);
  frame(ctx, state);

  // If tunneling occurs, ball.y - ball.r will be > brick.y + brick.h
  // because it jumped over the brick.
  assert.ok(state.ball.vy < 0, 'Ball should have bounced UP');
});

# To Fix

Symptôme : « La balle traverse les briques au lieu de rebondir »

## D1 — Absence de réflexion
- **Famille** : face vs coin
- **Symptôme joueur** : La balle traverse la brique sans changer de direction.
- **Cause** : `game/neon.js:164` — Le code détecte la collision (`collides(state.ball, brick)`) mais ne modifie pas la vitesse de la balle.
- **Invariant violé** : Toute collision avec une brique doit entraîner un rebond.
- **Déclencheur** : N'importe quelle collision avec une brique.
- **Attendu** : `vx` ou `vy` inversé selon la face touchée.
- **Référence** : https://noonat.github.io/intersect/ — AABB overlap detection.
- **Cas test** :
  ```js
  test('D1 - No bounce: ball should reflect when hitting a brick (TOP)', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y - 5; 
    state.ball.vy = 100; 
    state.ball.vx = 0;
    frame(dummyCtx, state);
    assert.ok(state.ball.vy < 0);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced UP`
- **Discrimine** : Une correction qui oublierait d'inverser la vitesse.
- **Vert quand** : Le cas test passe.
- **Révélé par** : Aucun.

## D2 — Mauvaise face / Coin
- **Famille** : face vs coin
- **Symptôme joueur** : La balle rebondit dans la mauvaise direction (ex: rebond horizontal sur le dessus).
- **Cause** : `game/neon.js:164` — Manque de calcul de la profondeur de pénétration pour déterminer l'axe de rebond.
- **Invariant violé** : L'axe de rebond doit être l'axe de la plus petite pénétration.
- **Déclencheur** : Collision sur le côté d'une brique avec `vy != 0`.
- **Attendu** : `vx` inversé si la pénétration X est moindre que la pénétration Y.
- **Référence** : https://manbeardgames.github.io/collision-detection/aabb-collision/
- **Cas test** :
  ```js
  test('D1 - No bounce: ball should reflect when hitting a brick (SIDE)', () => {
    const state = createState(1);
    const brick = state.bricks[0];
    state.ball.x = brick.x - 5; 
    state.ball.y = brick.y + brick.h / 2;
    state.ball.vx = 100; 
    state.ball.vy = 0;
    frame(dummyCtx, state);
    assert.ok(state.ball.vx < 0);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced LEFT`
- **Discrimine** : Une correction naïve qui inverserait systématiquement `vy`.
- **Vert quand** : Le cas test passe.
- **Révélé par** : D1.

## D3 — Double inversion
- **Famille** : double inversion (seam / ghost collision)
- **Symptôme joueur** : La balle traverse une rangée ou une colonne de briques.
- **Cause** : `game/neon.js:164` — Boucle `for (const brick of state.bricks)` qui peut inverser la vitesse plusieurs fois par frame.
- **Invariant violé** : Un rebond par passe et par axe.
- **Déclencheur** : Balle chevauchant deux briques simultanément.
- **Attendu** : La vitesse est inversée une seule fois.
- **Référence** :-
- **Cas test** :
  ```js
  test('D2 - Double inversion: ball should reflect only once even if hitting two bricks', () => {
    const state = createState(1);
    const b1 = state.bricks[0];
    const b2 = state.bricks[1];
    state.ball.x = b1.x + b1.w + 3; 
    state.ball.vx = 100;
    state.ball.vy = 0;
    frame(dummyCtx, state);
    assert.ok(state.ball.vx < 0);
  });
  ```
- **Rouge aujourd'hui** : `AssertionError [ERR_ASSERTION]: Ball should have bounced LEFT once`
- **Discrimine** : Une correction qui inverserait la vitesse pour chaque brique touchée sans vérifier la direction actuelle.
- **Vert quand** : Le cas test passe.
- **Révélé par** : D1.

## D4 — Traversée (Tunneling)
- **Famille** : traversée (tunneling)
- **Symptôme joueur** : À haute vitesse, la balle passe à travers les briques.
- **Cause** : `game/neon.js:136` — Détection discrète : si `ballSpeed * dt > BRICK_H`, la balle peut sauter la brique.
- **Invariant violé** : Aucun obstacle franchi sans rebond, quel que soit le pas.
- **Déclencheur** : `ballSpeed(6) * 0.05 >= 34px`.
- **Attendu** : La balle rebondit même si sa position `t` et `t+dt` encadrent la brique.
- **Référence** : https://gamedev.net/gameplay-programming/swept-aabb-collision-detection-and-response-r3084
- **Cas test** :
  ```js
  test('D3 - Tunneling: ball should not pass through brick at high speed', () => {
    const state = createState(6);
    const brick = state.bricks[0];
    state.ball.x = brick.x + brick.w / 2;
    state.ball.y = brick.y - 10; 
    state.ball.vy = 680; 
