edits.newText:
// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls, the paddle, and the bricks.
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle } = state;
  const subSteps = 4; // Divide dt to prevent tunneling
  const subDt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * subDt;
    ball.y += ball.vy * subDt;

    // Side walls
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    // Ceiling
    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Bricks
    for (const brick of state.bricks) {
      if (!brick.alive) continue;
      if (collides(ball, brick)) {
        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);

        const overlapX = Math.min(
          (ball.x + ball.r) - brick.x,
          (brick.x + brick.w) - (ball.x - ball.r)
        );
        const overlapY = Math.min(
          (ball.y + ball.r) - brick.y,
          (brick.y + brick.h) - (ball.y - ball.r)
        );

        if (overlapX < overlapY) {
          const hitLeft = ball.x < brick.x + brick.w / 2;
          if ((hitLeft && ball.vx > 0) || (!hitLeft && ball.vx < 0)) {
            ball.vx *= -1;
            ball.x += (ball.vx > 0) ? -overlapX : overlapX;
          }
        } else {
          const hitTop = ball.y < brick.y + brick.h / 2;
          if ((hitTop && ball.vy > 0) || (!hitTop && ball.vy < 0)) {
            ball.vy *= -1;
            ball.y += (ball.vy > 0) ? -overlapY : overlapY;
          }
        }
      }
    }

    // Exit through the bottom: ball lost
    if (ball.y - ball.r > HEIGHT) {
      return true;
    }
  }
  return false;
}

